# Let us write a universal CRC-32 tester
# Standard CRC-32 parameters:
# poly (normal or reversed):
# 0x04C11DB7 (IEEE / POSIX / MPEG-2 / etc.)
# 0x1EDC6F41 (Castagnoli / CRC-32C)
# 0xA833982B (Koopman)
# 0x814141AB (Q)

with open("/app/samples/s06_empty.jrn", "rb") as f:
    d = f.read()
data = d[:-4]
exp_be = int.from_bytes(d[-4:], "big")
exp_le = int.from_bytes(d[-4:], "little")

def crc32_generic(data, poly, init, refin, refout, xorout):
    # bit-by-bit
    reg = init
    if refin:
        for b in data:
            reg ^= b
            for _ in range(8):
                if reg & 1:
                    reg = (reg >> 1) ^ poly
                else:
                    reg >>= 1
    else:
        for b in data:
            reg ^= (b << 24)
            for _ in range(8):
                if reg & 0x80000000:
                    reg = ((reg << 1) & 0xffffffff) ^ poly
                else:
                    reg = (reg << 1) & 0xffffffff
    if refout != refin:
        # reverse bits of reg
        r = 0
        for i in range(32):
            if reg & (1 << i):
                r |= (1 << (31 - i))
        reg = r
    return reg ^ xorout

# Common reversed polynomials:
# IEEE: 0xEDB88320 (normal 0x04C11DB7)
# Castagnoli: 0x82F63B78 (normal 0x1EDC6F41)
# Koopman: 0xEB31D82E (normal 0x741B8CD7)
polys = [
    (0x04C11DB7, 0xEDB88320, "IEEE"),
    (0x1EDC6F41, 0x82F63B78, "Castagnoli"),
    (0x741B8CD7, 0xEB31D82E, "Koopman"),
    (0x814141AB, 0xD5828281, "Q"),
    (0x000000AF, 0xF5000000, "CRC-32/XFER"),
]

found = False
for p_norm, p_rev, name in polys:
    for init in [0x00000000, 0xffffffff]:
        for xorout in [0x00000000, 0xffffffff]:
            for refin in [False, True]:
                poly = p_rev if refin else p_norm
                c = crc32_generic(data, poly, init, refin, refin, xorout)
                if c == exp_be or c == exp_le:
                    print(f"FOUND CRC match! {name}, init={hex(init)}, refin={refin}, xorout={hex(xorout)}, matches {'BE' if c == exp_be else 'LE'}")
                    found = True
if not found:
    print("No standard CRC-32 match found.")
'

