#!/usr/bin/env python3
import sys
import json
import zlib
from datetime import datetime, timezone

# ISO 4217 minor units
ZERO_DECIMAL_CURRENCIES = {
    "BIF", "CLP", "DJF", "GNF", "ISK", "JPY", "KMF", "KRW",
    "PYG", "RWF", "UGX", "UYI", "VND", "VUV", "XAF", "XOF", "XPF"
}
THREE_DECIMAL_CURRENCIES = {
    "BHD", "IQD", "JOD", "KWD", "LYD", "OMR", "TND"
}
FOUR_DECIMAL_CURRENCIES = {
    "CLF", "UYW"
}

def get_currency_decimals(code: str) -> int:
    if code in ZERO_DECIMAL_CURRENCIES:
        return 0
    if code in THREE_DECIMAL_CURRENCIES:
        return 3
    if code in FOUR_DECIMAL_CURRENCIES:
        return 4
    return 2

def read_leb128(data: bytes, pos: int) -> tuple[int, int]:
    val = 0
    shift = 0
    while True:
        if pos >= len(data):
            raise ValueError("Unexpected EOF while reading LEB128")
        b = data[pos]
        pos += 1
        val |= (b & 0x7f) << shift
        shift += 7
        if (b & 0x80) == 0:
            break
    return val, pos

def decode_jrn(data: bytes) -> dict:
    if len(data) < 17:
        raise ValueError("File too short")
    if data[:4] != b"JRN\x01":
        raise ValueError("Invalid magic number")

    expected_crc = int.from_bytes(data[-4:], "little")
    actual_crc = zlib.crc32(data[4:-4])
    if expected_crc != actual_crc:
        raise ValueError(f"CRC32 mismatch: expected {hex(expected_crc)}, got {hex(actual_crc)}")

    n_rec = int.from_bytes(data[4:6], "big")
    base_ts = int.from_bytes(data[6:10], "big")
    default_curr = data[10:13].decode("ascii")

    pos = 13
    n_accts = data[pos]
    pos += 1
    accts = []
    for _ in range(n_accts):
        l = data[pos]
        pos += 1
        if pos + l > len(data) - 4:
            raise ValueError("Account name exceeds file boundary")
        accts.append(data[pos:pos+l].decode("utf-8"))
        pos += l

    records = []
    memo_dict = []
    cur_ts = base_ts

    for idx in range(n_rec):
        if pos >= len(data) - 4:
            raise ValueError("Unexpected EOF while reading records")
        flags = data[pos]
        pos += 1
        d_ts, pos = read_leb128(data, pos)
        cur_ts += d_ts
        if pos >= len(data) - 4:
            raise ValueError("Unexpected EOF while reading account index")
        acct_idx = data[pos]
        pos += 1
        if acct_idx >= len(accts):
            raise ValueError(f"Invalid account index: {acct_idx}")

        amt_raw, pos = read_leb128(data, pos)

        curr = default_curr
        if flags & 0x04:
            if pos + 3 > len(data) - 4:
                raise ValueError("Unexpected EOF while reading currency code")
            curr = data[pos:pos+3].decode("ascii")
            pos += 3

        memo = None
        if flags & 0x01:
            mlen, pos = read_leb128(data, pos)
            if pos + mlen > len(data) - 4:
                raise ValueError("Unexpected EOF while reading memo bytes")
            memo = bytes([b ^ 0x5a for b in data[pos:pos+mlen]]).decode("utf-8")
            pos += mlen
            memo_dict.append(memo)
        elif flags & 0x10:
            memo_idx, pos = read_leb128(data, pos)
            if memo_idx >= len(memo_dict):
                raise ValueError(f"Invalid memo reference index: {memo_idx}")
            memo = memo_dict[memo_idx]

        status = "pending" if (flags & 0x08) else "posted"
        scale = get_currency_decimals(curr)
        if scale == 0:
            amt_str = str(amt_raw)
        else:
            amt_str = str(amt_raw).rjust(scale + 1, "0")
            amt_str = amt_str[:-scale] + "." + amt_str[-scale:]
        if flags & 0x02:
            amt_str = "-" + amt_str

        dt = datetime.fromtimestamp(cur_ts, timezone.utc)
        ts_str = dt.strftime("%Y-%m-%dT%H:%M:%SZ")

        records.append({
            "index": idx,
            "timestamp": ts_str,
            "account": accts[acct_idx],
            "amount": amt_str,
            "currency": curr,
            "memo": memo,
            "status": status
        })

    if pos != len(data) - 4:
        raise ValueError(f"Trailing data before checksum: pos={pos}, expected={len(data)-4}")

    return {
        "default_currency": default_curr,
        "accounts": accts,
        "records": records
    }

def main():
    if len(sys.argv) < 2:
        sys.stderr.write("Usage: python jrndecode.py FILE.jrn\n")
        sys.exit(2)

    filepath = sys.argv[1]
    try:
        with open(filepath, "rb") as f:
            data = f.read()
    except Exception as e:
        sys.stderr.write(f"Error opening file: {e}\n")
        sys.exit(2)

    try:
        result = decode_jrn(data)
    except Exception as e:
        sys.stderr.write(f"Decode error: {e}\n")
        sys.exit(2)

    json.dump(result, sys.stdout, indent=2, ensure_ascii=False)
    sys.stdout.write("\n")
    sys.exit(0)

if __name__ == "__main__":
    main()
EOF
